<?php
/**
 * Recommendation Sites – admin login (username/email + password).
 * Credentials and the GitHub token live in _private/config.php, which is
 * generated by the GitHub Action from repository secrets and never stored in git.
 */

const RS_MAX_FAILS = 5;          // failed attempts allowed...
const RS_LOCK_WINDOW = 900;      // ...per 15 minutes, per IP
const RS_SESSION_HOURS = 12;

$RS_PRIVATE = __DIR__ . '/_private';
$RS_CONFIG_FILE = $RS_PRIVATE . '/config.php';

function rs_config() {
    global $RS_CONFIG_FILE;
    static $cfg = null;
    if ($cfg === null) {
        $cfg = is_file($RS_CONFIG_FILE) ? (include $RS_CONFIG_FILE) : [];
    }
    return is_array($cfg) ? $cfg : [];
}

function rs_start_session() {
    global $RS_PRIVATE;
    if (session_status() === PHP_SESSION_ACTIVE) return;
    $dir = $RS_PRIVATE . '/sessions';
    if (!is_dir($dir)) @mkdir($dir, 0700, true);
    if (is_dir($dir) && is_writable($dir)) session_save_path($dir);
    ini_set('session.gc_maxlifetime', (string)(RS_SESSION_HOURS * 3600));
    session_name('rs_admin');
    session_set_cookie_params([
        'lifetime' => RS_SESSION_HOURS * 3600,
        'path' => '/admin',
        'secure' => !empty($_SERVER['HTTPS']) && $_SERVER['HTTPS'] !== 'off',
        'httponly' => true,
        'samesite' => 'Lax',
    ]);
    session_start();
}

function rs_logged_in() {
    rs_start_session();
    return !empty($_SESSION['rs_user'])
        && !empty($_SESSION['rs_time'])
        && (time() - $_SESSION['rs_time']) < RS_SESSION_HOURS * 3600;
}

function rs_attempts_file() {
    global $RS_PRIVATE;
    return $RS_PRIVATE . '/attempts.json';
}

function rs_is_locked($ip) {
    $f = rs_attempts_file();
    $data = is_file($f) ? json_decode((string)@file_get_contents($f), true) : [];
    $list = array_filter($data[$ip] ?? [], fn($t) => $t > time() - RS_LOCK_WINDOW);
    return count($list) >= RS_MAX_FAILS;
}

function rs_record_fail($ip) {
    $f = rs_attempts_file();
    $data = is_file($f) ? json_decode((string)@file_get_contents($f), true) : [];
    if (!is_array($data)) $data = [];
    $data[$ip] = array_values(array_filter($data[$ip] ?? [], fn($t) => $t > time() - RS_LOCK_WINDOW));
    $data[$ip][] = time();
    @file_put_contents($f, json_encode($data), LOCK_EX);
}

function rs_clear_fails($ip) {
    $f = rs_attempts_file();
    $data = is_file($f) ? json_decode((string)@file_get_contents($f), true) : [];
    if (is_array($data) && isset($data[$ip])) {
        unset($data[$ip]);
        @file_put_contents($f, json_encode($data), LOCK_EX);
    }
}

function rs_check_credentials($login, $password) {
    $cfg = rs_config();
    $login = strtolower(trim($login));
    foreach (($cfg['users'] ?? []) as $u) {
        $names = array_filter([strtolower($u['username'] ?? ''), strtolower($u['email'] ?? '')]);
        if (in_array($login, $names, true) && password_verify($password, $u['hash'] ?? '')) {
            return $u['username'] ?: $u['email'];
        }
    }
    return false;
}

function rs_require_login() {
    rs_start_session();
    if (rs_logged_in()) {
        $_SESSION['rs_time'] = time(); // sliding session
        return;
    }
    $cfg = rs_config();
    $error = '';
    $ip = $_SERVER['REMOTE_ADDR'] ?? 'unknown';

    if (empty($cfg['users']) || empty($cfg['github_token'])) {
        rs_render_login('', true);
        exit;
    }

    if ($_SERVER['REQUEST_METHOD'] === 'POST') {
        $csrfOk = isset($_POST['csrf'], $_SESSION['rs_csrf']) && hash_equals($_SESSION['rs_csrf'], (string)$_POST['csrf']);
        if (rs_is_locked($ip)) {
            $error = 'Too many failed attempts. Please wait 15 minutes and try again.';
        } elseif (!$csrfOk) {
            $error = 'Your session expired. Please try again.';
        } else {
            $user = rs_check_credentials((string)($_POST['login'] ?? ''), (string)($_POST['password'] ?? ''));
            if ($user) {
                rs_clear_fails($ip);
                session_regenerate_id(true);
                $_SESSION['rs_user'] = $user;
                $_SESSION['rs_time'] = time();
                header('Location: ' . strtok($_SERVER['REQUEST_URI'], '?'));
                exit;
            }
            rs_record_fail($ip);
            usleep(600000);
            $error = 'Incorrect username/email or password.';
        }
    }
    rs_render_login($error, false);
    exit;
}

function rs_render_login($error, $notConfigured) {
    rs_start_session();
    if (empty($_SESSION['rs_csrf'])) $_SESSION['rs_csrf'] = bin2hex(random_bytes(16));
    header('Content-Type: text/html; charset=utf-8');
    header('X-Robots-Tag: noindex, nofollow');
    header('Cache-Control: no-store');
    $csrf = htmlspecialchars($_SESSION['rs_csrf']);
    $err = htmlspecialchars($error);
    ?><!doctype html>
<html lang="en"><head>
<meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1">
<meta name="robots" content="noindex, nofollow">
