.box{width:100%;max-width:400px;background:#fff;border-radius:22px;padding:34px 30px;box-shadow:0 30px 60px -20px rgba(0,0,0,.5)}
.brand{display:flex;align-items:center;gap:10px;font-weight:800;font-size:19px;color:#0b1f1a;margin-bottom:6px}.brand b{color:#0f9d6b}
h1{font-size:22px;margin:18px 0 4px;color:#0b1f1a}p.sub{margin:0 0 22px;color:#5d6f69;font-size:14px}
label{display:block;font-size:13px;font-weight:600;color:#22302c;margin:14px 0 6px}
input{width:100%;padding:13px 14px;border:1.5px solid #dbe5e1;border-radius:12px;font-size:16px;outline:none;transition:border .15s}
input:focus{border-color:#0f9d6b;box-shadow:0 0 0 4px rgba(15,157,107,.12)}
button{width:100%;margin-top:22px;padding:14px;border:0;border-radius:999px;font-weight:800;font-size:16px;cursor:pointer;background:linear-gradient(180deg,#ffd166,#f5a400);color:#2a1d00}
.err{background:#fff1ee;border:1px solid #ffd1c6;color:#a3361a;padding:10px 12px;border-radius:10px;font-size:14px;margin-bottom:6px}
.pw{position:relative}.pw span{position:absolute;right:12px;top:12px;cursor:pointer;font-size:13px;color:#5d6f69;user-select:none}
.foot{text-align:center;margin-top:18px;font-size:13px}.foot a{color:#5d6f69}
</style></head><body>
<form class="box" method="post" autocomplete="on">
  <div class="brand"><img src="/assets/img/logo.svg" width="34" height="34" alt="">Recommendation<b>Sites</b></div>
  <?php if ($notConfigured): ?>
    <h1>Admin not configured yet</h1>
    <p class="sub">Add the secrets <b>ADMIN_USERNAME</b>, <b>ADMIN_EMAIL</b>, <b>ADMIN_PASSWORD</b> and <b>ADMIN_GITHUB_TOKEN</b> in GitHub and run the deploy again.</p>
  <?php else: ?>
    <h1>Admin login</h1>
    <p class="sub">Sign in to manage your site.</p>
    <?php if ($err): ?><div class="err"><?= $err ?></div><?php endif; ?>
    <input type="hidden" name="csrf" value="<?= $csrf ?>">
    <label for="login">Username or email</label>
    <input id="login" name="login" type="text" autocomplete="username" required autofocus>
    <label for="password">Password</label>
    <div class="pw"><input id="password" name="password" type="password" autocomplete="current-password" required><span onclick="var i=document.getElementById('password');i.type=i.type==='password'?'text':'password';this.textContent=i.type==='password'?'Show':'Hide'">Show</span></div>
    <button type="submit">Sign in</button>
  <?php endif; ?>
  <p class="foot"><a href="/">← Back to the website</a></p>
</form>
</body></html><?php
}
